mapper.select:
SELECT * FROM t_voucher_entry
WHERE voucher_id = #{voucherId}
ORDER BY sort_order ASC

SELECT e.* FROM t_voucher_entry e
INNER JOIN t_voucher v ON v.id = e.voucher_id AND v.deleted = 0
WHERE e.subject_id = #{subjectId}
  AND e.deleted = 0
  AND v.period = #{period}
ORDER BY e.id ASC

SELECT e.* FROM t_voucher_entry e
INNER JOIN t_voucher v ON v.id = e.voucher_id AND v.deleted = 0
WHERE e.subject_id = #{subjectId}
  AND e.deleted = 0
  AND v.period = #{period}

  AND DATE(v.created_at) >= #{startDate}


  AND DATE(v.created_at) <= #{endDate}

ORDER BY v.created_at ASC, e.id ASC

SELECT e.voucher_id AS voucherId, v.voucher_no AS voucherNo, DATE(v.created_at) AS voucherDate, e.subject_id AS subjectId, e.summary AS summary, e.debit AS debit, e.credit AS credit, e.sort_order AS sortOrder FROM t_voucher_entry e INNER JOIN t_voucher v ON v.id = e.voucher_id AND v.deleted = 0 WHERE e.subject_id = #{subjectId} AND e.deleted = 0 AND v.period = #{period}
AND v.status = 'POSTED'
AND DATE(v.created_at) >= #{startDate}
AND DATE(v.created_at) <= #{endDate}
ORDER BY v.created_at ASC, e.sort_order ASC, e.id ASC

SELECT t.subject_id AS subjectId, t.dim_value AS dimensionValue, COALESCE(SUM(t.debit), 0) AS debitTotal, COALESCE(SUM(t.credit), 0) AS creditTotal FROM ( SELECT e.subject_id, e.debit, e.credit, e.assist_json ->> #{dimensionField} AS dim_value FROM t_voucher_entry e INNER JOIN t_voucher v ON v.id = e.voucher_id AND v.deleted = 0 WHERE e.deleted = 0 AND v.period = #{period} AND jsonb_exists(e.assist_json, #{dimensionField})
AND e.assist_json ->> #{dimensionField} = CAST(#{dimensionValue} AS TEXT)
) t GROUP BY t.subject_id, t.dim_value ORDER BY t.subject_id ASC

SELECT t.subject_id AS subjectId, t.dim_value AS dimensionValue, COALESCE(SUM(t.debit), 0) AS debitTotal, COALESCE(SUM(t.credit), 0) AS creditTotal FROM ( SELECT e.subject_id, e.debit, e.credit, e.assist_json ->> #{dimensionField} AS dim_value FROM t_voucher_entry e INNER JOIN t_voucher v ON v.id = e.voucher_id AND v.deleted = 0 WHERE e.deleted = 0 AND v.period < #{period} AND jsonb_exists(e.assist_json, #{dimensionField})
AND e.assist_json ->> #{dimensionField} = CAST(#{dimensionValue} AS TEXT)
) t GROUP BY t.subject_id, t.dim_value ORDER BY t.subject_id ASC
